import React, { useState } from 'react';
import './CSS/Cart.css';

export default function CartPage() {
  // Mock cart items (Replace with your React Context or State management later)
  const [cartItems, setCartItems] = useState([
    { id: '1', title: 'Wireless Smartphone', price: 999.00, quantity: 1, image: 'https://via.placeholder.com/80' },
    { id: '2', title: 'Smart Watch Series X', price: 299.00, quantity: 2, image: 'https://via.placeholder.com/80' }
  ]);

  const updateQuantity = (id, delta) => {
    setCartItems(cartItems.map(item => {
      if (item.id === id) {
        const newQty = item.quantity + delta;
        return newQty > 0 ? { ...item, quantity: newQty } : item;
      }
      return item;
    }));
  };

  const removeItem = (id) => {
    setCartItems(cartItems.filter(item => item.id !== id));
  };

  const subtotal = cartItems.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const shipping = subtotal > 0 ? 15.00 : 0;
  const total = subtotal + shipping;

  return (
    <div className="cart-page-container">
      <h2>Shopping Cart</h2>
      <p className="cart-subtitle">Review your selected items before proceeding to checkout</p>

      {cartItems.length === 0 ? (
        <div className="empty-cart">
          <p>Your cart is empty.</p>
        </div>
      ) : (
        <div className="cart-grid">
          {/* Cart Items List */}
          <div className="cart-items-list">
            {cartItems.map(item => (
              <div key={item.id} className="cart-item-card">
                <img src={item.image} alt={item.title} className="cart-thumb" />
                <div className="cart-item-details">
                  <h4>{item.title}</h4>
                  <span className="cart-item-price">${item.price.toFixed(2)}</span>
                </div>
                <div className="cart-qty-controls">
                  <button onClick={() => updateQuantity(item.id, -1)}>-</button>
                  <span>{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)}>+</button>
                </div>
                <button className="btn-remove" onClick={() => removeItem(item.id)}>🗑️</button>
              </div>
            ))}
          </div>

          {/* Cart Summary Card */}
          <div className="cart-summary-card">
            <h3>Order Summary</h3>
            <div className="summary-row">
              <span>Subtotal</span>
              <span>${subtotal.toFixed(2)}</span>
            </div>
            <div className="summary-row">
              <span>Estimated Shipping</span>
              <span>${shipping.toFixed(2)}</span>
            </div>
            <hr />
            <div className="summary-row total">
              <span>Total</span>
              <span>${total.toFixed(2)}</span>
            </div>
            <button className="btn-checkout" onClick={() => alert('Proceeding to Checkout!')}>
              Proceed to Checkout
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
